    push(normalized.replace(/てもらうとします[。！？!?]?$/u, 'て'));
    push(normalized.replace(/てもらうことにする[。！？!?]?$/u, 'て'));
    push(normalized.replace(/てくれる(でしょ|よな|んでしょ|わよね)[。！？!?]?$/u, 'て'));
    push(normalized.replace(/ちゃうねん(で)?[。！？!?]?$/u, 'て'));
