    push(normalized.replace(/てもた[。！？!?]?$/u, 'て'));
    push(normalized.replace(/てもええでしょうか[。！？!?]?$/u, 'て'));
    // pass CCXIX
    push(normalized.replace(/てくれれば(?:助かる|有難い|万々歳|言うことなし|文句なし|申し分ない|十分|それで(?:十分|いい)?|良し|ok|よし)[。！？!?]?$/u, 'て'));
    push(normalized.replace(/てくださいます(?:ぞ|んで|よね|から|なあ|わよ|わね|わ|かのう|かの|かぞ|かいな|かい|こと|のね|もの)[。！？!?]?$/u, 'て'));
    push(normalized.replace(/てなんし|てなんせ|てたまえや|てたもれぞ[。！？!?]?$/u, 'て'));
    // pass CCXX
    push(normalized.replace(/ておく(?:がいい|とよい|のだ|ぞ|がええ)[。！？!?]?$/u, 'て'));
    push(normalized.replace(/ておき(?:ます(?:から|んで|わ)?|ましょうか|たいものだ|たいのだが)[。！？!?]?$/u, 'て'));
    push(normalized.replace(/ておいてええよ|といておいていいよ[。！？!?]?$/u, 'て'));
    push(normalized.replace(/てもらいたく候|てほしく候|ておくれ候|るように候|たく存じ候|てよろしゅうございます[。！？!?]?$/u, 'て'));
    push(normalized.replace(/てもらう[どだ]|てもらわんか|てくれんならん|とくれたい|とくれぞ|とくれたら[。！？!?]?$/u, 'て'));
    push(normalized.replace(/てお願い(?:します(?:ぞ|ね|わ|よ|って)?|しとります|してんの|だから|だ|を)[。！？!?]?$/u, 'て'));
    push(normalized.replace(/てお頼み(?:します|申します)|てお願いさせてください|てくださいじゃ|てくださいまへんか[。！？!?]?$/u, 'て'));
    push(normalized.replace(/てしまいませ|てしまいだまれ|てしまいだめ|てもうていいよ|てもうてもええで|てみなはれ|てみてほしいよ|てみてくれんか|てみてもらいたい[。！？!?]?$/u, 'て'));
    // pass CCXXI
    push(normalized.replace(/て進ぜ(?:よう|ます)|て差し上げ(?:よう|ます)|てしかるべ(?:し|きだ|き)|て然るべき(?:だ)?[。！？!?]?$/u, 'て'));
    push(normalized.replace(/てほしゅうございます|ておきなまし|てなまし|てやす(?:よ)?|てどす(?:え)?|ておし(?:てや)?|てやで|てやんす|てやんせ|てくれやんす|てくれは(?:ったら|れ|りな)|てはり(?:ますか|な)|てみはりな|てもらいは(?:る|れ)[。！？!?]?$/u, 'て'));
    push(normalized.replace(/てほしな|てもらいたかねえ|てもらいますねん|てもらいなはれ|てもらっちゃ|てもらお(?:や|かな)[。！？!?]?$/u, 'て'));
    push(normalized.replace(/てもらう(?:わい|ぞう|ぜよ|がや|みゃあ|ねん|す|っしょ|っちゃ|んやで|んやから|んじゃけえ|んだべ|んだな|んだべさ|っぺ(?:よ|な)?|ぺ|だっぺ|ぞな|ぞね|ぜい|さかい(?:に)?|のう|なあ|なー|なのう|ものをね|ものを|ものだが|ものね)[。！？!?]?$/u, 'て'));
    // pass CCXXII: て+方言単助詞粒子
    push(normalized.replace(/て(?:せ|ず|ぬ|ぺ|す|ぐ|ら|やねん|やね|で|じゃあ|じゃけえ|じゃけ|じゃ|けえ|ちゃ|みゃあ|みゃ|にゃあ|にゃ|ぎゃ|ずら|っちゃ|けん|ばい|たい|とよ|とて|と|ごとね|ごと|わいな|わい|さかいに|さかい|のう|ぞな|ぞね|ぜい|ぞい|だべ|だっぺ|っぺ|がす|んじゃあ|じゃろう|じゃろ|にょ|んかい|んのかい|なの|のお|ぬか|まろ|ぞぉ|ぜぇ|わー|さー|ー)[。！？!?]?$/u, 'て'));
    push(normalized.replace(/てて(?:や)?[。！？!?]?$/u, 'て'));
    // pass CCXXIII
    push(normalized.replace(/なさいまして|なされませ|なされまして|なすって(?:ください)?|やがりなさい|やりなさい|あそばせ|あそばして|あそばし|なむ|なもう?|てんし|ませい|ませ[。！？!?]?$/u, 'て'));
    push(normalized.replace(/たまえまし|たまえぞよ|てぇん|てやぁ|てよかろう|てよからん|てくだされ(?:や|い)|てくださん(?:し|せ)|てくれさんし|てくれせんかい|てくれん(?:しゃい|せんかい|やろか)|てくれはらんか[。！？!?]?$/u, 'て'));
    push(normalized.replace(/てくれぬか(?:もの|のう|しらん)|てくれねえか(?:な|のう)[。！？!?]?$/u, 'て'));
    push(normalized.replace(/てくれりゃ(?:嬉しい|助かる|ありがてえ|万々歳|最高|文句なし|言うことなし)|てくれたなら(?:嬉しい|助かる|幸い)|てもらったなら(?:嬉しい|助かる)|るのだまし[。！？!?]?$/u, 'て'));
    // ちゃう+地域粒子
    push(normalized.replace(/ちゃう(?:がええ|がいい|べし|が吉|ぞよ|がな|わい|ぞう|ぜよ|けん|ばい|のう|さかい|だべ|っぺ|にゃあ|みゃあ|っちゃ|んや|ぞな|ぞね|なあ|のん|がや|だがや|だら|じゃん|っす|す|っしょ|だって|がす|てや)[。！？!?]?$/u, 'て'));
    // pass CCXXIV
    push(normalized.replace(/てくださいそうろう|てくださいせ|てくだされませ|てほしゅう(?:ございますね|ね)|てはり|てすん(?:な)?|てじゃん|てじゃわ|てきざい|てながら|てえんか|てやがら|てがも|てけ[ぇえのさ]|てくん(?:ない|なよ)|てなんね|てあれよ|てもろう(?:て)?|てもろて(?:もええ|な)|てもろたらええ|てなー|てなら(?:ーん|んか)|てくりゃ(?:れ|あ)|てくれんのね|ておいとき|ておいてー|てちょき|ておくべきでしょう|ておいた方がよろしい|ちゃっといて|といてよ[。！？!?]?$/u, 'て'));
    // pass CCXXVI
    push(normalized.replace(/てクレメンス|てくれめんす|てくんろ|てはんな|てみや|てけれ|てしぇ|てねん|てしょー?|てなんしょ|てやれよ|てくれや[でな]|てくれなはれ|てくれまへん(?:やろか|かね)|てもらわんと(?:困る)?|てくれりゃあええ|てええ(?:んで|やん|わ|かも)|ておいてええ|といといて|ときゃいいんだ[。！？!?]?$/u, 'て'));
    // pass CCXXVII
    push(normalized.replace(/てもらおうと|てもらうとかして[。！？!?]?$/u, 'て'));
    push(normalized.replace(/ることにした(?:よ|んだ)$/u, 'て'));
    // pass CCXXVIII
    push(normalized.replace(/ちゃえば|ちゃったら|といたれ|ときやれ|とけや|てみよ|てみようぜ|てぷりーず|てもん[。！？!?]?$/u, 'て'));
    // pass CCXXIX
    push(normalized.replace(/ちまえ|ちまったら|ちまいたい|ちまう(?:ぞ|よ|わ)?|ておこ|とこうぜ[。！？!?]?$/u, 'て'));
    push(normalized.replace(/(て|で)(?:あげて|あげ(?:る|ます)[ねよわか]?|くれる|くださる|くださいます)[。！？!?]?$/u, '$1'));
    push(normalized.replace(/(て|で)(?:くれ|くださ)ちゃう[。！？!?]?$/u, '$1'));
    push(normalized.replace(/(て|で)もら(?:う|える|った|います|えます|ってもいい|っていい)[。！？!?]?$/u, '$1'));
    // Double-suffix requests: '読んであげてください' → '読んで'.
    push(normalized.replace(/(て|で)あげて(?:ください|下さい)[。！？!?]?$/u, '$1'));
    push(normalized.replace(/(て|で)くださると[。！？!?]?$/u, '$1'));
    push(normalized.replace(/(て|で)いただければ[。！？!?]?$/u, '$1'));
    push(normalized.replace(/(て|で)ほしいん(?:だけど|ですけど|ですが)[。！？!?]?$/u, '$1'));
    push(normalized.replace(/(て|で)ほしい(?:な|ね|わ)?[。！？!?]?$/u, '$1'));
    // Volitional contraction: '閉じちゃお' → '閉じて'.
    push(normalized.replace(/ちゃおう?(?:かな|か|よ|ぜ|わ|な)?[。！？!?]?$/u, 'て'));
    push(normalized.replace(/じゃおう?(?:かな|か|よ|ぜ|わ|な)?[。！？!?]?$/u, 'で'));
    // Obligation: '読まなきゃ' → '読んで' (あ-row godan) / '閉じなきゃ' → '閉じて'.
    const NAKYA = {
      'ま': 'んで', 'ら': 'って', 'わ': 'って', 'か': 'いて', 'が': 'いで',
      'さ': 'して', 'た': 'って', 'な': 'んで', 'ば': 'んで', 'ぱ': 'んで' };
    push(normalized.replace(/([まらわかがさたなばぱ])(?:なきゃ|なきゃあ|なくちゃ|なくっちゃ|なければ|ないと|ねば|ならん|んと|なあかん|んとあかん)[。！？!?]?$/u,
      (m, ch) => NAKYA[ch] || ch));
    push(normalized.replace(/(?:なきゃ|なきゃあ|なくちゃ|なくっちゃ|なければ|ないと(?:ね)?|ねば|ならん|んと|なあかん|んとあかん)[。！？!?]?$/u, 'て'));
    // とく系残置: '閉じといてくださいね'/'閉じとこかな' → '閉じて' (ておく意は既存ルールへ譲渡)
    push(normalized.replace(/[とど]いて(?:ください|くれ|もらえますか|もらえませんか|ほしい)?(?:ね)?[。！？!?]?$/u, 'て'));
    push(normalized.replace(/[とど]こ(?:かな|か|う)?[。！？!?]?$/u, 'て'));
