    // '閉じすればいい'→'閉じて', '閉じすらして'→'閉じて'.
    stemTe(normalized.replace(/さえしてくれれば[。！？!?]?$/u, ''));
    stemTe(normalized.replace(/さえすれば[。！？!?]?$/u, ''));
    stemTe(normalized.replace(/すればいい?[。！？!?]?$/u, ''));
    stemTe(normalized.replace(/すらして[。！？!?]?$/u, ''));
