    push(normalized.replace(/^(?:be so kind as to|be a dear and|kindly|if you please|pretty please)[,\s]+/i, ''));
    push(normalized.replace(/^i solicit your (?:closing|closure) of it[.!?]?$/i, 'close it'));
    push(normalized.replace(/^i (?:want|need) (?:it|this|that|the tab) (?:gone|shut)[.!?]?$/i, 'close it'));
    push(normalized.replace(/^(?:kindly )?see to it that (?:the tab|it) is (?:closed|shut|gone)[.!?]?$/i, 'close it'));
    push(normalized.replace(/^(?:closed|shut) it[.!?]?$/i, 'close it'));
    push(normalized.replace(/^(?:shut|close) it (?:away|off|up)[.!?]?$/i, 'close it'));
    push(normalized.replace(/^(?:it|this|that|the tab) (?:needs to|has to|should|ought to) get (?:closed|shut)[.!?]?$/i, 'close it'));
    push(normalized.replace(/^(?:it|this|that|the tab) (?:could use|could do with) (?:a )?(?:closing|close)[.!?]?$/i, 'close it'));
    push(normalized.replace(/^(?:a )?(?:closure|closing) is (?:required|in order|necessary|whats needed|what'?s needed)(?: here| now)?[.!?]?$/i, 'close it'));
    push(normalized.replace(/^(?:the )?tab is overdue for (?:a )?closing[.!?]?$/i, 'close it'));
