    push(normalized.replace(/^pull the plug on it[.!?]?$/i, 'close it'));
    push(normalized.replace(/^(?:shut|close) the book on it[.!?]?$/i, 'close it'));
    push(normalized.replace(/^give me the pleasure of it being closed[.!?]?$/i, 'close it'));
    push(normalized.replace(/^i would hate for it to stay open[.!?]?$/i, 'close it'));
    push(normalized.replace(/^i would (?:love|like) for it to be closed[.!?]?$/i, 'close it'));
    push(normalized.replace(/^i would prefer (?:if|that) you (?:closed|close) it[.!?]?$/i, 'close it'));
    push(normalized.replace(/^i would appreciate (?:if|that) you (?:closed|close) it[.!?]?$/i, 'close it'));
    push(normalized.replace(/^i would not mind if you (?:closed|close) it[.!?]?$/i, 'close it'));
    push(normalized.replace(/^i would not object if you (?:closed|close) it[.!?]?$/i, 'close it'));
    push(normalized.replace(/^i would not (?:be (?:opposed|averse|adverse) to|object to) you closing it[.!?]?$/i, 'close it'));
    push(normalized.replace(/^(?:thank you|thanks) kindly for closing it[.!?]?$/i, 'close it'));
    push(normalized.replace(/^thanking you in advance for closing it[.!?]?$/i, 'close it'));
    push(normalized.replace(/^i (?:feel|think|believe|figure|reckon|guess)(?: like)? (?:it|this|that|the tab) (?:should|needs to|has to|ought to|wants|wants to|got to|get) ?(?:be |get )?(?:closed|shut|gone|closing|go)[.!?]?$/i, 'close it'));
